#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=19

# Production values live in a gitignored file at the repo root, not in
# apps/api/.env (that one is local development).
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE=".env.production"

# already_saved KEY...: when every KEY is already in ENV_FILE, load them and
# offer to skip the stage. Lets a re-run jump past finished work.
already_saved() {
  local k v
  for k in "$@"; do
    v=$(_existing "$k" || true)
    [[ -n "$v" ]] || return 1
    printf -v "$k" '%s' "$v"
  done
  note "Saved on an earlier run: $*"
  confirm "Skip this stage?"
}

# ask_match ask|ask_secret KEY "Prompt" REGEX "Hint": ask until the value
# matches REGEX, so a mis-paste is caught here rather than in production.
ask_match() {
  local fn="$1" key="$2" prompt="$3" re="$4" hint="$5"
  while :; do
    "$fn" "$key" "$prompt"
    [[ "${!key}" =~ $re ]] && return 0
    warn "$hint"
  done
}

# to_clipboard VALUE: put VALUE on the clipboard so it is pasted, not shown.
to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# on_server CMD: run CMD as root on the server with the operator key.
on_server() {
  ssh -i "$SSH_KEY_PATH" -o StrictHostKeyChecking=accept-new "root@$SERVER_IP" "$@"
}

# wait_for_a NAME: re-check public DNS until NAME resolves to the server.
wait_for_a() {
  local got
  while :; do
    got=$(dig +short @1.1.1.1 A "$1" | tail -n1)
    if [[ "$got" == "$SERVER_IP" ]]; then
      printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$1" "$got"; return 0
    fi
    warn "$1 resolves to '${got:-nothing}' yet, not $SERVER_IP."
    confirm "Check again? (No continues anyway)" || return 0
  done
}

TUNNEL_PID=""
trap '[[ -n "$TUNNEL_PID" ]] && kill "$TUNNEL_PID" 2>/dev/null; true' EXIT

banner "Homelibra beta infrastructure (#42, provisioning)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: add the domain"
if ! already_saved DOMAIN; then
  say "Cloudflare will hold DNS for the domain you bought at Namecheap."
  open_url "https://dash.cloudflare.com/?to=/:account/domains/overview"
  step "Sign up or sign in, then click 'Onboard a domain'."
  step "Enter the apex domain (homelibra.com), let it scan records, Continue."
  step "Pick the Free plan."
  step "Keep the tab open: the next stage needs the two nameservers it shows."
  ask DOMAIN "Domain you added [homelibra.com]:"
  DOMAIN="${DOMAIN:-homelibra.com}"
  write_env DOMAIN "$DOMAIN"
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Namecheap: point nameservers at Cloudflare"
say "Done on an earlier run? Press Enter through this stage."
open_url "https://www.namecheap.com/myaccount/login.aspx"
step "Domain List (left sidebar) → 'Manage' next to $DOMAIN → Domain tab."
step "In the 'Nameservers' dropdown choose the 'Custom DNS' option."
step "Enter the two Cloudflare nameservers, then click the green checkmark."
note "Namecheap's own host records and forwarding stop applying from now on."
note "Propagation can take up to 24 hours; the following stages don't wait for it."
pause "Nameservers saved? Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "SSH key for the server"
if ! already_saved SSH_KEY_PATH; then
  say "The server accepts key logins only. A dedicated key keeps it separate."
  ask SSH_KEY_PATH "Private key path [$HOME/.ssh/homelibra_ed25519]:"
  SSH_KEY_PATH="${SSH_KEY_PATH:-$HOME/.ssh/homelibra_ed25519}"
  if [[ ! -f "$SSH_KEY_PATH" ]]; then
    if confirm "No key at $SSH_KEY_PATH. Generate one now (you'll set a passphrase)?"; then
      ssh-keygen -t ed25519 -f "$SSH_KEY_PATH" -C "homelibra-operator"
    else
      warn "Create the key yourself, then re-run this wizard."; exit 1
    fi
  fi
  write_env SSH_KEY_PATH "$SSH_KEY_PATH"
fi
if to_clipboard "$(cat "$SSH_KEY_PATH.pub")"; then
  note "The public key is on your clipboard for the next stage."
else
  note "Public key to paste in the next stage:"; say "$(cat "$SSH_KEY_PATH.pub")"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: project, SSH key, firewall"
say "Done on an earlier run? Press Enter through this stage."
open_url "https://console.hetzner.com/"
step "Create a project named Homelibra (or open it)."
step "Security → SSH Keys → 'Add SSH Key': paste the public key, name it."
step "Firewalls → 'Create Firewall', name it homelibra."
step "Inbound rules: TCP 22, TCP 80, TCP 443, sources Any IPv4 + Any IPv6. Nothing else."
note "Coolify's panel port 8000 stays closed; we reach it through an SSH tunnel."
step "Click 'CREATE FIREWALL'."
pause "Firewall created? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Hetzner: create the server"
if ! already_saved SERVER_IP SERVER_LOCATION; then
  step "Servers → 'Add server'."
  step "Type: CX23 (x86, 2 vCPU / 4 GB, 40 GB). x86 matches the amd64 images CI builds."
  step "Location: Nuremberg (nbg1), or Falkenstein (fsn1) if nbg1 has no CX23."
  step "Image: Ubuntu 24.04. SSH keys: tick the key you just added."
  step "Firewalls: tick homelibra. Backups: off (Coolify dumps the database)."
  step "Name: homelibra-1 → 'CREATE & BUY NOW'. Copy the public IPv4 shown."
  ask_match ask SERVER_LOCATION "Location code (nbg1 or fsn1):" '^(nbg1|fsn1)$' "Enter nbg1 or fsn1."
  ask_match ask SERVER_IP "Server IPv4:" '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' "That isn't an IPv4 address."
  write_env SERVER_LOCATION "$SERVER_LOCATION"
  write_env SERVER_IP "$SERVER_IP"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: DNS records"
say "Done on an earlier run? Press Enter, and the DNS check still runs."
open_url "https://dash.cloudflare.com/?to=/:account/:zone/dns/records"
say "Choose $DOMAIN if asked. Add two records, each with Proxy status OFF (grey cloud, 'DNS only'):"
step "'Add record' → Type A, Name @, Content $SERVER_IP → Save."
step "'Add record' → Type A, Name coolify, Content $SERVER_IP → Save."
note "Proxy must stay off: Coolify gets its own Let's Encrypt certificates."
pause "Both records saved? Press Enter to check public DNS."
note "This waits on the Namecheap nameserver change; Ctrl-C and re-run later is fine."
wait_for_a "$DOMAIN"
wait_for_a "coolify.$DOMAIN"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Server: key-only SSH"
say "Checking how sshd is configured on $SERVER_IP …"
SSHD=$(on_server 'sshd -T | grep -Ei "^(permitrootlogin|passwordauthentication|kbdinteractiveauthentication) "')
printf '%s\n' "$SSHD" | sed 's/^/    /'
if grep -qiE ' yes$' <<<"$SSHD"; then
  say "Password logins are still possible. The fix is a drop-in that sshd reads first:"
  note "/etc/ssh/sshd_config.d/00-homelibra.conf: PasswordAuthentication no, KbdInteractiveAuthentication no, PermitRootLogin prohibit-password"
  if confirm "Write it and reload sshd?"; then
    on_server 'printf "PasswordAuthentication no\nKbdInteractiveAuthentication no\nPermitRootLogin prohibit-password\n" > /etc/ssh/sshd_config.d/00-homelibra.conf && sshd -t && systemctl reload ssh && sshd -T | grep -Ei "^(permitrootlogin|passwordauthentication|kbdinteractiveauthentication) "' | sed 's/^/    /'
  else
    SKIPPED+=("key-only SSH on $SERVER_IP")
  fi
else
  printf '  %s✓%s key-only already\n' "$GREEN" "$RESET"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Coolify: install"
if on_server 'test -d /data/coolify/source' 2>/dev/null; then
  printf '  %s✓%s Coolify is already installed; not re-running the installer.\n' "$GREEN" "$RESET"
  pause
else
  say "Runs Coolify's official installer on the server as root (a few minutes):"
  note "curl -fsSL https://cdn.coollabs.io/coolify/install.sh | bash"
  if confirm "Install Coolify on $SERVER_IP now?"; then
    on_server -t 'curl -fsSL https://cdn.coollabs.io/coolify/install.sh | bash'
    pause "Installer finished. Press Enter."
  else
    SKIPPED+=("Coolify install"); warn "Skipped; the next stages need it."; pause
  fi
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Coolify: admin account and panel domain"
COOLIFY_URL="https://coolify.$DOMAIN"
say "Opening an SSH tunnel to the panel (port 8000 is closed to the internet)."
ssh -i "$SSH_KEY_PATH" -o ExitOnForwardFailure=yes -N -L 18000:localhost:8000 -L 6001:localhost:6001 -L 6002:localhost:6002 "root@$SERVER_IP" &
TUNNEL_PID=$!
sleep 2
kill -0 "$TUNNEL_PID" 2>/dev/null || { warn "Tunnel failed: is local port 18000, 6001 or 6002 in use?"; exit 1; }
open_url "http://localhost:18000"
warn "The first person to register becomes admin with root on the server: register now."
step "Register your admin account (password into your password manager)."
step "Settings → General → URL: $COOLIFY_URL, tick 'Redirect HTTP to HTTPS' → 'Save changes'."
step "Settings → Advanced → Access → Registration: disable it."
pause "All three done? Press Enter to close the tunnel."
kill "$TUNNEL_PID" 2>/dev/null || true; TUNNEL_PID=""
open_url "$COOLIFY_URL"
step "Sign in at $COOLIFY_URL. The certificate can take a minute to appear."
pause "Panel works over HTTPS? Press Enter."
write_env COOLIFY_URL "$COOLIFY_URL"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Coolify: two-factor authentication"
say "Done on an earlier run? Press Enter through this stage."
open_url "$COOLIFY_URL/profile"
step "User menu → Profile → Two-factor Authentication → 'Configure 2FA'."
step "Confirm your password, scan the QR code with your authenticator."
step "Enter the one-time code → 'Validate 2FA'."
step "Save the recovery codes in your password manager."
pause "2FA on? Press Enter."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Hetzner Object Storage: backup bucket"
if ! already_saved BACKUP_S3_BUCKET BACKUP_S3_LOCATION BACKUP_S3_ACCESS_KEY BACKUP_S3_SECRET_KEY; then
  [[ "$SERVER_LOCATION" == nbg1 ]] && SUGGEST=fsn1 || SUGGEST=nbg1
  say "Backups go to another location than the server ($SERVER_LOCATION), so: $SUGGEST."
  open_url "https://console.hetzner.com/"
  step "Homelibra project → Object Storage → 'Create Bucket'."
  step "Location: $SUGGEST. Name: homelibra-backups (names are global; add a suffix if taken)."
  step "Visibility: Private → 'Create & Buy now'."
  ask_match ask BACKUP_S3_LOCATION "Bucket location [$SUGGEST]:" '^(fsn1|nbg1|hel1)?$' "Enter fsn1, nbg1 or hel1."
  BACKUP_S3_LOCATION="${BACKUP_S3_LOCATION:-$SUGGEST}"
  [[ "$BACKUP_S3_LOCATION" == "$SERVER_LOCATION" ]] && warn "Same location as the server: a site outage takes both."
  ask_match ask BACKUP_S3_BUCKET "Bucket name:" '^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$' "Lowercase letters, digits, dots and hyphens only."
  step "Security → 'S3 Credentials' tab → 'Generate credentials', description coolify-backups."
  warn "The secret key is shown only once: paste it here before closing that window."
  ask BACKUP_S3_ACCESS_KEY "Access key (top box):"
  ask_secret BACKUP_S3_SECRET_KEY "Secret key (bottom box):"
  write_env BACKUP_S3_LOCATION "$BACKUP_S3_LOCATION"
  write_env BACKUP_S3_BUCKET "$BACKUP_S3_BUCKET"
  write_env BACKUP_S3_ENDPOINT "https://$BACKUP_S3_LOCATION.your-objectstorage.com"
  write_env BACKUP_S3_ACCESS_KEY "$BACKUP_S3_ACCESS_KEY"
  write_env BACKUP_S3_SECRET_KEY "$BACKUP_S3_SECRET_KEY"
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Coolify: S3 backup destination"
say "Done on an earlier run? Press Enter through this stage."
open_url "$COOLIFY_URL"
step "Sidebar 'S3 Storage' → 'New storage'. Fill in:"
note "    Name:       hetzner-$BACKUP_S3_LOCATION-backups"
note "    Protocol:   https"
note "    Host:       $BACKUP_S3_LOCATION.your-objectstorage.com"
note "    Bucket:     $BACKUP_S3_BUCKET"
note "    Region:     $BACKUP_S3_LOCATION"
note "    Access Key: $BACKUP_S3_ACCESS_KEY"
pause "Press Enter to put the Secret Key on your clipboard."
to_clipboard "$BACKUP_S3_SECRET_KEY" && note "Secret key copied: paste it into Secret Key." \
  || note "No clipboard tool: copy BACKUP_S3_SECRET_KEY from $ENV_FILE."
step "'Validate Connection & Continue'. If Region is rejected, try eu-central."
note "Schedule and 14-day retention are set on the database itself, in the deploy wizard."
pause "Storage validated? Press Enter."

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Resend: verify the sending domain"
say "Done on an earlier run? Press Enter through this stage."
open_url "https://resend.com/domains"
step "Sign up or sign in → 'Add Domain': $DOMAIN, region eu-west-1 (Ireland)."
note "The region can't be changed later without deleting the domain."
step "Records tab: use 'Sign in to Cloudflare' to add them, or add each by hand."
note "By hand: MX send, TXT send (SPF), TXT resend._domainkey (DKIM), all DNS only."
step "In Cloudflare also add TXT _dmarc with content: v=DMARC1; p=none;"
step "Wait for Resend to show the domain as Verified (often ~15 min)."
pause "Domain verified? Press Enter."

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Resend: API key"
if ! already_saved RESEND_API_KEY MAIL_FROM; then
  open_url "https://resend.com/api-keys"
  step "Create an API key named homelibra-production."
  step "Permission: Sending access. Domain: $DOMAIN."
  warn "The key is shown once."
  ask_match ask_secret RESEND_API_KEY "API key (re_…):" '^re_' "Resend keys start with re_."
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  write_env MAIL_FROM "Homelibra <giris@$DOMAIN>"
fi

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Sentry: EU organization and projects"
if ! already_saved SENTRY_ORG SENTRY_DSN_API SENTRY_DSN_APP; then
  open_url "https://sentry.io/signup/"
  step "Create the organization with Data Storage Location: European Union (EU)."
  warn "The region is fixed for the org's lifetime; a US org would need replacing."
  step "Projects → 'Create Project' → Node.js (or Hono) → name homelibra-api."
  step "Copy its DSN (Project Settings → Client Keys (DSN))."
  ask_match ask SENTRY_DSN_API "API DSN:" '^https://[0-9a-f]+@o[0-9]+\.ingest\..*sentry\.io/[0-9]+$' "Expected https://<key>@o<id>.ingest….sentry.io/<project>."
  step "Projects → 'Create Project' → React Native → name homelibra-app. Copy its DSN."
  ask_match ask SENTRY_DSN_APP "App DSN:" '^https://[0-9a-f]+@o[0-9]+\.ingest\..*sentry\.io/[0-9]+$' "Expected https://<key>@o<id>.ingest….sentry.io/<project>."
  [[ "$SENTRY_DSN_API$SENTRY_DSN_APP" == *".de.sentry.io"* ]] || warn "The DSNs don't mention .de.sentry.io: check the org really is in the EU."
  step "Organization slug: Settings → General Settings → Organization Slug."
  ask_match ask SENTRY_ORG "Organization slug:" '^[a-z0-9-]+$' "Slugs are lowercase letters, digits and hyphens."
  write_env SENTRY_DSN_API "$SENTRY_DSN_API"
  write_env SENTRY_DSN_APP "$SENTRY_DSN_APP"
  write_env SENTRY_ORG "$SENTRY_ORG"
fi

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Sentry: auth token for source maps"
if ! already_saved SENTRY_AUTH_TOKEN; then
  open_url "https://$SENTRY_ORG.sentry.io/settings/"
  step "Settings → Developer Settings → 'Organization Tokens' → create one, name homelibra-ci."
  warn "The token is shown once."
  ask_match ask_secret SENTRY_AUTH_TOKEN "Org token (sntrys_…):" '^sntrys_' "Organization tokens start with sntrys_."
  write_env SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
  note "The next stage hands it to EAS: release builds upload source maps with it."
fi

# ── 17 ────────────────────────────────────────────────────────────────────
stage "Expo: link the app to an EAS project"
if ! already_saved EAS_PROJECT_ID; then
  say "No Expo account yet? Sign up first."
  open_url "https://expo.dev/signup"
  pause "Have an account? Press Enter to sign in from the terminal."
  (cd apps/app && npx eas-cli@latest login)
  say "eas init creates the project and writes extra.eas.projectId and owner to apps/app/app.json."
  if confirm "Run eas init in apps/app?"; then
    (cd apps/app && npx eas-cli@latest init)
    EAS_PROJECT_ID=$(node -p "require('./apps/app/app.json').expo.extra?.eas?.projectId ?? ''")
    if [[ -n "$EAS_PROJECT_ID" ]]; then
      write_env EAS_PROJECT_ID "$EAS_PROJECT_ID"
      note "apps/app/app.json changed: commit it with the deploy work."
    else
      SKIPPED+=("EAS project id (not found in apps/app/app.json)")
    fi
  else
    SKIPPED+=("eas init")
  fi
  pause
fi
# Outside the check above so a re-run can still push it. Without it, release
# builds fail at the Sentry source map upload.
if [[ -n "${SENTRY_AUTH_TOKEN:-}" ]] && confirm "Give EAS builds the Sentry token (preview and production)?"; then
  (cd apps/app && npx eas-cli@latest env:create --name SENTRY_AUTH_TOKEN --value "$SENTRY_AUTH_TOKEN" \
    --visibility secret --environment preview --environment production --force --non-interactive)
else
  SKIPPED+=("SENTRY_AUTH_TOKEN on EAS: preview and production builds will fail")
fi

# ── 18 ────────────────────────────────────────────────────────────────────
stage "GitHub: let Coolify pull private images"
say "Done on an earlier run? Press Enter through this stage."
say "GHCR accepts only classic tokens. This one is read-only and goes straight into Coolify."
open_url "https://github.com/settings/tokens/new?scopes=read:packages"
step "Note: coolify-ghcr-pull. Scope: read:packages only. Pick an expiry and diarise it."
step "'Generate token' and copy it."
open_url "$COOLIFY_URL"
step "Coolify → Registries → 'Log in' → GHCR preset."
GH_LOGIN=$(gh api user -q .login 2>/dev/null || true)
step "Username: ${GH_LOGIN:-your GitHub username}. Token: paste → 'Log in'."
note "Not saved locally. When it expires, image pulls fail: repeat this stage."
pause "Coolify logged in to GHCR? Press Enter."

# ── 19 ────────────────────────────────────────────────────────────────────
stage "Better Auth secret"
# Never regenerated on a re-run: a new secret would sign everyone out.
if [[ -n "$(_existing BETTER_AUTH_SECRET || true)" ]]; then
  printf '  %s✓%s kept the BETTER_AUTH_SECRET already in %s\n' "$GREEN" "$RESET" "$ENV_FILE"
else
  say "Generated here; no one needs to see it."
  write_env BETTER_AUTH_SECRET "$(openssl rand -base64 48 | tr -d '\n')"
fi
note "Everything for the deploy wizard is now in $ENV_FILE."
pause

finish
}

run_wizard "$@"; exit
